export const UK_IE_MASK_WATER = { dark: "#2C353C", light: "#d4dadc" } as const;

// CARTO water colors (dark_all / light_all tiles) so the mask blends into the
// sea around the islands instead of painting an obvious rectangle: dark
// #2C353C, light #d4dadc. Add right after the basemap raster layer.
export function addUkIeMaskLayer(map: Map, prefersDark: boolean): void {
  const feature: GeoJSON.Feature = {
    type: "Feature",
    properties: {},
    geometry: { type: "Polygon", coordinates: UK_IE_MASK_RINGS },
  };
  map.addSource("uk-ie-mask", { type: "geojson", data: feature });
  map.addLayer({
    id: "uk-ie-mask",
    type: "fill",
    source: "uk-ie-mask",
    paint: {
      "fill-color": prefersDark ? UK_IE_MASK_WATER.dark : UK_IE_MASK_WATER.light,
    },
  });
}
